      g.add(canopy);
      const fascia = boxMesh(17.2, 0.7, 0.4, standard(d.color, { roughness: 0.5, metalness: 0.2 }));
      fascia.position.set(30, 5.0, 11.1); g.add(fascia);
      for (const px of [23, 37]) for (const pz of [1.6, 10.4]) {
