        const con = boxMesh(12, 2.7, 2.6, cmat);
        con.position.set(46 + rand() * 5, 1.38 + (k > 1 ? 2.72 : 0), -22 + (k % 2) * 3);
        con.rotation.y = Math.PI / 2;
        g.add(con);
