@font-face {
  font-family: 'Inter';
  src: url('./assets/fonts/inter-latin-400-normal.woff2') format('woff2');
  font-weight: 400; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Inter';
  src: url('./assets/fonts/inter-latin-500-normal.woff2') format('woff2');
  font-weight: 500; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Inter';
  src: url('./assets/fonts/inter-latin-600-normal.woff2') format('woff2');
  font-weight: 600; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Inter';
  src: url('./assets/fonts/inter-latin-700-normal.woff2') format('woff2');
  font-weight: 700; font-style: normal; font-display: swap;
}

:root {
  --bg: #090d11;
  --bg-2: #0f151b;
  --panel: rgba(17, 24, 31, 0.72);
  --panel-2: rgba(20, 28, 36, 0.9);
  --line: rgba(238, 232, 218, 0.13);
  --line-strong: rgba(238, 232, 218, 0.28);
  --ink: #f0ece2;
  --muted: rgba(231, 227, 216, 0.55);
  --muted-2: rgba(231, 227, 216, 0.35);
  --orange: #e39a44;
  --orange-2: #f4b25a;
  --green: #80bd84;
  --red: #d95e47;
  --cond: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --sans: 'Inter', system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: 100%; height: 100%; overflow: hidden; }
body {
  background: var(--bg); color: var(--ink);
  font-family: var(--sans); font-size: 14px;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
button, input { font: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; background: #06090c; }
#scene, #scene canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
#scene canvas { outline: none; }
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 52%, transparent 42%, rgba(2, 4, 7, 0.25) 78%, rgba(2, 4, 7, 0.55) 100%),
    linear-gradient(to bottom, rgba(3, 6, 9, 0.28), transparent 18%, transparent 72%, rgba(3, 6, 9, 0.35));
}
#grain {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0.16;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 240 240' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.42'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}

.glass {
  background: linear-gradient(160deg, rgba(27, 37, 47, 0.74), rgba(10, 15, 20, 0.66));
  border: 1px solid var(--line);
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.34), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(16px) saturate(1.2);
  -webkit-backdrop-filter: blur(16px) saturate(1.2);
}
.eyebrow {
  font-family: var(--cond); font-size: 12px; font-weight: 600; letter-spacing: 0.19em;
  color: var(--orange); text-transform: uppercase; display: flex; align-items: center; gap: 9px;
}
.live-dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--orange); display: inline-block;
  box-shadow: 0 0 10px rgba(227, 154, 68, 0.8); animation: pulse 2.4s infinite;
}
@keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.4; transform: scale(0.7); } }

.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 14px;
  font-family: var(--cond); font-weight: 600; letter-spacing: 0.12em; font-size: 15px;
  padding: 15px 28px; border: 1px solid transparent; border-radius: 3px;
  transition: transform .18s ease, background .18s ease, border-color .18s ease, color .18s ease;
  text-transform: uppercase; overflow: hidden;
}
.btn::after {
  content: ''; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 30%, rgba(255,255,255,0.14), transparent 70%);
  transform: translateX(-120%); transition: transform .5s ease;
}
.btn:hover::after { transform: translateX(120%); }
.btn:hover { transform: translateY(-1px); }
.btn.primary { background: var(--orange); color: #17130e; }
.btn.primary:hover { background: var(--orange-2); }
.btn.ghost { border-color: var(--line-strong); color: var(--ink); background: rgba(255,255,255,0.025); }
.btn.ghost:hover { border-color: var(--orange); color: var(--orange-2); background: rgba(227,154,68,0.06); }
.btn.dark-ghost { color: var(--muted); border-color: rgba(255,255,255,0.06); background: transparent; }
.btn.dark-ghost:hover { color: var(--ink); border-color: var(--line); }
.btn.wide { width: 100%; }
.btn.sm { padding: 10px 18px; font-size: 13px; }
.btn span { font-size: 18px; line-height: 1; }
.btn:disabled { opacity: 0.35; pointer-events: none; }

.icon-btn {
  width: 42px; height: 42px; display: grid; place-items: center; border-radius: 4px;
  border: 1px solid var(--line); color: var(--muted); font-size: 18px;
  transition: color .18s, border-color .18s, background .18s;
}
.icon-btn:hover { color: var(--ink); border-color: var(--orange); background: rgba(227,154,68,0.08); }

/* ======================================================= SCREENS */
.screen { position: absolute; inset: 0; z-index: 10; display: flex; flex-direction: column; }
.screen.overlay {
  align-items: center; justify-content: center;
  background: rgba(4, 7, 10, 0.62); backdrop-filter: blur(7px); -webkit-backdrop-filter: blur(7px);
}

/* ======================================================= TITLE */
#menu {
  padding: 34px 46px 24px;
  background:
    radial-gradient(ellipse at 25% 45%, rgba(6, 10, 14, 0.05), rgba(6, 10, 14, 0.6) 62%, rgba(4, 7, 10, 0.85) 100%),
    linear-gradient(90deg, rgba(4, 7, 10, 0.7) 0%, rgba(4, 7, 10, 0.24) 48%, rgba(4, 7, 10, 0.1) 100%);
  animation: fadeIn 1.2s ease both;
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.title-top { display: flex; align-items: center; justify-content: space-between; }
.brand-lockup { display: flex; align-items: center; gap: 14px; }
.brand-mark {
  width: 48px; height: 48px; border: 1px solid rgba(227,154,68,0.55); border-radius: 3px;
  display: grid; place-items: center; color: var(--orange); background: rgba(8,12,16,0.5);
  box-shadow: inset 0 0 22px rgba(227,154,68,0.08);
}
.brand-mark svg { width: 34px; height: 34px; }
.brand-text { display: flex; flex-direction: column; line-height: 1; }
.brand-text strong {
  font-family: var(--cond); font-size: 25px; font-weight: 700; letter-spacing: 0.22em; color: var(--ink);
}
.brand-text span {
  font-family: var(--cond); font-size: 10px; font-weight: 500; letter-spacing: 0.44em; color: var(--orange); margin-top: 5px;
}
.title-meta { display: flex; align-items: center; gap: 18px; }
.version { font-family: var(--cond); font-size: 11px; letter-spacing: 0.18em; color: var(--muted-2); }
.title-main {
  flex: 1; display: flex; align-items: center; justify-content: space-between; gap: 40px;
  padding: 0 4vw 0 3vw; min-height: 0;
}
.hero-copy { max-width: 720px; animation: rise .9s .15s ease both; }
@keyframes rise { from { opacity: 0; transform: translateY(22px); } to { opacity: 1; transform: none; } }
.hero-copy h1 {
  font-family: var(--cond); font-weight: 800; font-size: clamp(86px, 10.4vw, 168px);
  line-height: 0.78; letter-spacing: -0.015em; margin: 24px 0 30px; color: var(--ink);
  text-shadow: 0 12px 40px rgba(0,0,0,0.55);
}
.hero-copy h1 em { font-style: normal; color: var(--orange); }
.hero-copy p {
  font-size: 15px; line-height: 1.65; color: rgba(235, 231, 221, 0.68); max-width: 470px;
  text-shadow: 0 2px 18px rgba(0,0,0,0.6); margin-bottom: 34px;
}
.title-actions { display: flex; gap: 12px; flex-wrap: wrap; align-items: center; }
.career-strip {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; margin-top: 34px;
  border-radius: 4px; overflow: hidden; max-width: 600px;
}
.career-strip > div {
  padding: 16px 18px; background: rgba(8, 12, 16, 0.35);
  display: flex; flex-direction: column; gap: 5px;
}
.career-strip span { font-family: var(--cond); font-size: 10px; letter-spacing: 0.19em; color: var(--muted-2); }
.career-strip b { font-family: var(--cond); font-size: 25px; font-weight: 600; letter-spacing: 0.02em; }
.title-side { width: 330px; flex-shrink: 0; display: flex; flex-direction: column; gap: 14px; animation: rise 1s .35s ease both; }
.feature-card { padding: 22px 24px; border-radius: 4px; }
.feature-top { display: flex; justify-content: space-between; font-family: var(--cond); font-size: 10px; letter-spacing: 0.18em; color: var(--muted-2); }
.feature-top span:last-child { color: var(--orange); }
.feature-name { font-family: var(--cond); font-size: 48px; font-weight: 700; line-height: 1; margin-top: 22px; letter-spacing: 0.01em; }
.feature-name em { font-style: normal; color: var(--orange); }
.feature-sub { font-family: var(--cond); font-size: 10px; letter-spacing: 0.16em; color: var(--muted); margin-top: 8px; }
.feature-specs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 22px; }
.feature-specs div { border-top: 1px solid var(--line); padding-top: 12px; display: flex; flex-direction: column; gap: 5px; }
.feature-specs span { font-family: var(--cond); font-size: 9px; letter-spacing: 0.17em; color: var(--muted-2); }
.feature-specs b { font-family: var(--cond); font-size: 18px; font-weight: 600; }
.feature-line { height: 1px; background: var(--line); margin: 22px 0 14px; }
.feature-note { font-size: 11px; line-height: 1.6; color: var(--muted); }
.online-pill {
  align-self: flex-start; padding: 10px 14px; border: 1px solid var(--line); border-radius: 30px;
  font-family: var(--cond); font-size: 10px; letter-spacing: 0.15em; color: var(--muted);
  background: rgba(7,10,14,0.42); backdrop-filter: blur(8px); display: flex; align-items: center; gap: 9px;
}
.title-footer {
  display: flex; align-items: center; gap: 12px; padding-top: 18px; border-top: 1px solid rgba(255,255,255,0.07);
  font-family: var(--cond); font-size: 10px; letter-spacing: 0.17em; color: var(--muted-2);
}
.footer-right { margin-left: auto; color: rgba(227,154,68,0.5); }

/* ======================================================= HUD */
#hud { position: absolute; inset: 0; z-index: 8; pointer-events: none; }
#hud .glass { pointer-events: auto; }
.hud-top {
  position: absolute; top: 22px; left: 24px; right: 24px;
  display: flex; align-items: flex-start; justify-content: space-between; gap: 16px;
}
.contract-card { width: 330px; padding: 16px 18px 14px; border-radius: 4px; }
.contract-row { display: flex; justify-content: space-between; align-items: baseline; margin-top: 9px; }
.contract-cargo { font-family: var(--cond); font-size: 25px; font-weight: 600; letter-spacing: 0.01em; }
.contract-pay { font-family: var(--cond); font-size: 23px; font-weight: 600; color: var(--orange); }
.route-line { display: flex; align-items: center; gap: 9px; margin-top: 3px; font-family: var(--cond); font-size: 12px; letter-spacing: 0.08em; color: var(--muted); }
.route-arrow { color: var(--orange); }
.route-city.dest { color: var(--ink); }
.contract-meta {
  display: flex; justify-content: space-between; gap: 8px; margin-top: 11px; padding-top: 9px;
  border-top: 1px solid var(--line); font-family: var(--cond); font-size: 10px; letter-spacing: 0.09em; color: var(--muted-2);
}
.nav-pill {
  position: absolute; left: 50%; transform: translateX(-50%); top: 0;
  display: flex; align-items: center; gap: 14px; padding: 11px 20px 11px 13px; border-radius: 40px;
}
.nav-arrow {
  width: 34px; height: 34px; border-radius: 50%; background: rgba(227,154,68,0.14); color: var(--orange);
  display: grid; place-items: center; font-size: 14px; transition: transform .2s ease;
}
.nav-copy { display: flex; flex-direction: column; gap: 2px; }
.nav-copy strong { font-family: var(--cond); font-size: 16px; letter-spacing: 0.06em; font-weight: 600; }
.nav-copy span { font-family: var(--cond); font-size: 10px; letter-spacing: 0.1em; color: var(--muted-2); }
.nav-copy b { color: var(--orange); font-weight: 600; }
.top-right { display: flex; align-items: flex-start; gap: 10px; }
.top-stat { display: flex; align-items: center; gap: 16px; padding: 11px 16px; border-radius: 4px; }
.clock-block { display: flex; flex-direction: column; gap: 3px; }
.clock { font-family: var(--cond); font-size: 25px; font-weight: 600; line-height: 1; letter-spacing: 0.04em; }
.weather { font-family: var(--cond); font-size: 10px; letter-spacing: 0.11em; color: var(--muted-2); }
.top-stat .divider { width: 1px; height: 34px; background: var(--line); }
.wallet-block { display: flex; flex-direction: column; gap: 3px; text-align: right; }
.money { font-family: var(--cond); font-size: 24px; font-weight: 600; color: var(--orange); line-height: 1; }
.level { font-family: var(--cond); font-size: 9px; letter-spacing: 0.12em; color: var(--muted-2); }
#btn-pause { width: 44px; height: 44px; background: rgba(12,18,24,0.7); }

.hud-bottom {
  position: absolute; bottom: 22px; left: 24px; right: 24px;
  display: flex; align-items: flex-end; justify-content: space-between; gap: 20px;
}
.map-wrap { position: relative; width: 190px; height: 190px; border-radius: 50%; overflow: hidden; padding: 8px; }
#minimap { width: 100%; height: 100%; border-radius: 50%; }
.map-head {
  position: absolute; top: 14px; left: 0; right: 0; display: flex; justify-content: space-between; padding: 0 19px;
  font-family: var(--cond); font-size: 9px; letter-spacing: 0.14em; color: rgba(238,234,224,0.7);
}
.map-scale {
  position: absolute; bottom: 17px; left: 50%; transform: translateX(-50%);
  font-family: var(--cond); font-size: 8px; letter-spacing: 0.15em; color: var(--muted-2);
  border-bottom: 1px solid rgba(238,234,224,0.35); padding-bottom: 1px; width: 34px; text-align: center;
}
.center-hud {
  display: flex; flex-direction: column; align-items: center; gap: 12px; margin-bottom: 6px; flex: 1;
}
.prompt {
  padding: 10px 20px; border-radius: 3px; font-family: var(--cond); font-size: 12px; letter-spacing: 0.13em;
  color: var(--ink); white-space: nowrap; animation: rise .3s ease both;
}
.prompt b { color: var(--orange); }
.speed-limit {
  width: 58px; height: 58px; border-radius: 50%; background: #f2eee4; border: 6px solid #c9312a;
  display: grid; place-items: center; box-shadow: 0 8px 22px rgba(0,0,0,0.4);
  font-family: var(--cond); font-size: 25px; font-weight: 700; color: #172027;
}
.speed-limit.speeding { animation: speedPulse .6s infinite; }
@keyframes speedPulse { 50% { box-shadow: 0 0 0 9px rgba(201,49,42,0.22); } }
.warnings { display: flex; gap: 8px; }
.warn-chip {
  font-family: var(--cond); font-size: 10px; letter-spacing: 0.1em; padding: 5px 10px;
  border: 1px solid rgba(217,94,71,0.4); background: rgba(217,94,71,0.12); color: #f0a08e; border-radius: 2px;
}
.dash-wrap { width: 265px; padding: 10px 12px 12px; border-radius: 4px; }
#speedo { width: 100%; display: block; }
.dash-footer { display: grid; grid-template-columns: 1fr 1fr; gap: 7px 12px; padding-top: 7px; border-top: 1px solid var(--line); }
.dash-item { display: flex; align-items: center; gap: 6px; grid-column: span 1; }
.dash-item:nth-child(3) { grid-column: span 2; }
.dash-item span { font-family: var(--cond); font-size: 8px; letter-spacing: 0.12em; color: var(--muted-2); }
.dash-item b { font-family: var(--cond); font-size: 10px; font-weight: 500; color: var(--muted); margin-left: auto; }
.mini-bar { flex: 1; height: 3px; background: rgba(255,255,255,0.12); border-radius: 2px; overflow: hidden; }
.mini-bar i { display: block; height: 100%; width: 50%; background: var(--green); transition: width .2s; }
.mini-bar.damage i { background: var(--orange); }

#notifications {
  position: absolute; top: 96px; left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 7px; pointer-events: none;
}
.toast {
  background: rgba(12,18,24,0.88); border: 1px solid var(--line); border-left: 2px solid var(--orange);
  padding: 9px 16px; border-radius: 2px; font-family: var(--cond); font-size: 12px; letter-spacing: 0.08em;
  animation: toastIn .3s ease both; backdrop-filter: blur(10px); color: var(--ink); max-width: 520px; text-align: center;
}
.toast.good { border-left-color: var(--green); }
.toast.bad { border-left-color: var(--red); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }

#tutorial {
  position: absolute; left: 50%; bottom: 235px; transform: translateX(-50%);
  padding: 18px 22px; border-radius: 4px; width: 460px; pointer-events: auto;
  animation: rise .4s ease both;
}
.tut-title { font-family: var(--cond); font-size: 13px; letter-spacing: 0.16em; color: var(--orange); margin-bottom: 13px; }
.tut-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px 16px; margin-bottom: 15px; }
.tut-grid div { display: flex; align-items: center; gap: 7px; }
.tut-grid span { font-size: 11px; color: var(--muted); }
kbd {
  display: inline-grid; place-items: center; min-width: 22px; height: 22px; padding: 0 5px;
  border: 1px solid var(--line-strong); border-bottom-width: 2px; border-radius: 3px;
  font-family: var(--cond); font-size: 10px; color: var(--ink); background: rgba(255,255,255,0.05);
}
#touch-controls { display: none; }

/* ======================================================= DISPATCH */
#jobboard {
  padding: 26px 34px 22px;
  background: linear-gradient(180deg, rgba(4,7,10,0.78), rgba(4,7,10,0.9));
  backdrop-filter: blur(7px);
}
.panel-header {
  display: flex; align-items: center; gap: 34px; padding-bottom: 18px; border-bottom: 1px solid var(--line);
}
.brand-lockup.small .brand-mark { width: 38px; height: 38px; }
.brand-lockup.small .brand-mark svg { width: 27px; height: 27px; }
.brand-lockup.small .brand-text strong { font-size: 20px; }
.brand-lockup.small .brand-text span { font-size: 8px; }
.tabs { display: flex; gap: 6px; }
.tab {
  font-family: var(--cond); font-size: 12px; letter-spacing: 0.14em; color: var(--muted-2);
  padding: 9px 18px; border: 1px solid transparent; border-radius: 3px;
}
.tab.active { color: var(--ink); border-color: var(--line); background: rgba(255,255,255,0.04); }
.tab:hover { color: var(--ink); }
.header-stats { margin-left: auto; display: flex; align-items: center; gap: 24px; }
.header-stats div { display: flex; flex-direction: column; gap: 2px; text-align: right; }
.header-stats span { font-family: var(--cond); font-size: 9px; letter-spacing: 0.16em; color: var(--muted-2); }
.header-stats b { font-family: var(--cond); font-size: 21px; font-weight: 600; }
.header-stats b#jb-money { color: var(--orange); }
.tab-page { flex: 1; min-height: 0; display: flex; gap: 30px; padding-top: 24px; }
.board-left { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.board-title { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 18px; }
.board-title h2, .garage-left h2 { font-family: var(--cond); font-weight: 700; font-size: 40px; letter-spacing: 0.01em; margin-top: 5px; }
.refresh { font-family: var(--cond); font-size: 10px; letter-spacing: 0.12em; color: var(--muted-2); }
.refresh b { color: var(--muted); }
.job-list { display: flex; flex-direction: column; gap: 9px; overflow-y: auto; padding-right: 6px; }
.job-item {
  display: grid; grid-template-columns: 58px 1fr 130px 120px 30px; align-items: center; gap: 16px;
  padding: 15px 18px; border: 1px solid var(--line); border-radius: 3px;
  background: rgba(15,22,29,0.45); transition: border-color .18s, background .18s, transform .18s;
  cursor: pointer; position: relative;
}
.job-item:hover { border-color: rgba(227,154,68,0.4); background: rgba(227,154,68,0.05); transform: translateX(3px); }
.job-item.selected { border-color: var(--orange); background: rgba(227,154,68,0.08); }
.job-item.selected::before { content: ''; position: absolute; left: -1px; top: 12px; bottom: 12px; width: 2px; background: var(--orange); }
.job-icon {
  width: 48px; height: 48px; border: 1px solid var(--line); border-radius: 2px; display: grid; place-items: center;
  font-family: var(--cond); font-size: 9px; letter-spacing: 0.1em; color: var(--orange); background: rgba(0,0,0,0.2);
}
.job-main { display: flex; flex-direction: column; gap: 3px; }
.job-main strong { font-family: var(--cond); font-size: 19px; font-weight: 600; letter-spacing: 0.02em; }
.job-main span { font-size: 11px; color: var(--muted-2); }
.job-route { font-family: var(--cond); font-size: 12px; letter-spacing: 0.06em; color: var(--muted); display: flex; flex-direction: column; gap: 3px; }
.job-route b { color: var(--ink); font-weight: 500; }
.job-money { text-align: right; display: flex; flex-direction: column; gap: 3px; }
.job-money b { font-family: var(--cond); font-size: 23px; font-weight: 600; color: var(--orange); }
.job-money span { font-family: var(--cond); font-size: 9px; letter-spacing: 0.1em; color: var(--muted-2); }
.job-go { color: var(--muted-2); font-size: 18px; transition: color .18s, transform .18s; }
.job-item:hover .job-go { color: var(--orange); transform: translateX(3px); }
