    this.composer.addPass(new OutputPass());

    this.audio = new GameAudio();
    this.career = loadJSON(SAVE_KEY, defaultCareer());
    this.settings = loadJSON(SETTINGS_KEY, defaultSettings());
    this.state = 'loading';
