    this.dragging = false;
    this.lastMouse = { x: 0, y: 0 };
    this.keys = Object.create(null);
    this.touch = { throttle: 0, brake: 0, steer: 0, horn: false };
    this.game = {
      state: 'menu', career: this.career, settings: this.settings, jobs: [], job: null,
