function levelProgress(xp) {
  const level = levelForXp(xp);
  const lo = 300 * (level - 1) * (level - 1);
  const hi = 300 * level * level;
  return { level, progress: clamp((xp - lo) / Math.max(1, hi - lo), 0, 1), lo, hi };
}

