404:     document.querySelectorAll('[data-touch]').forEach((btn) => {
405:       const action = btn.dataset.touch;
406:       const down = (e) => {
407:         e.preventDefault();
408:         if (action === 'throttle') this.touch.throttle = 1;
409:         if (action === 'brake') this.touch.brake = 1;
410:         if (action === 'left') this.touch.steer = 1;
411:         if (action === 'right') this.touch.steer = -1;
412:         if (action === 'horn') { this.audio.setHorn(true); this.touch.horn = true; }
413:         if (action === 'camera') this.cycleCamera();
414:       };
415:       const up = (e) => {
416:         e.preventDefault();
417:         if (action === 'throttle') this.touch.throttle = 0;
418:         if (action === 'brake') this.touch.brake = 0;
419:         if (action === 'left' || action === 'right') this.touch.steer = 0;
420:         if (action === 'horn') { this.audio.setHorn(false); this.touch.horn = false; }
421:       };
422:       btn.addEventListener('pointerdown', down);
423:       btn.addEventListener('pointerup', up);
424:       btn.addEventListener('pointercancel', up);
425:       btn.addEventListener('pointerleave', up);
426:     });
427:     window.addEventListener('resize', () => this.resize());
428:     window.addEventListener('beforeunload', () => this.save());
429:     document.addEventListener('visibilitychange', () => {
430:       if (document.hidden && this.state === 'driving') this.openPause();
431:     });
432:   }
