434:   onKeyDown(e) {
435:     const code = e.code;
436:     if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab'].includes(code)) e.preventDefault();
437:     if (e.repeat) return;
438:     this.keys[code] = true;
439:     if (code === 'Escape') {
440:       if (this.state === 'driving') this.openPause();
441:       else if (this.state === 'paused') this.resumeGame();
442:       else if (this.state === 'settings') this.closeSettings();
443:       else if (this.state === 'help') this.closeHelp();
444:       else if (this.state === 'map') this.closeMap();
445:       return;
446:     }
447:     if (this.state !== 'driving') return;
448:     if (code === 'KeyC') this.cycleCamera();
449:     else if (code === 'KeyH') this.audio.setHorn(true);
450:     else if (code === 'KeyL') {
451:       this.truck.lightsOn = !this.truck.lightsOn;
452:       this.toast(this.truck.lightsOn ? 'Headlights on.' : 'Headlights off.');
453:     } else if (code === 'KeyE') {
454:       if (this.truck.fuel <= 0) { this.toast('No fuel. Call recovery with R.', 'bad'); return; }
455:       this.truck.engineOn = !this.truck.engineOn;
456:       this.audio.airBrake();
457:       this.toast(this.truck.engineOn ? 'Engine started.' : 'Engine stopped.');
458:     } else if (code === 'KeyM') this.openMap();
459:     else if (code === 'KeyR') this.recoverTruck();
460:     else if (code === 'Enter' && this.nearDeliveryZone() && this.truck.getSpeedKmh() < 2) {
461:       this.deliveryHold = 2.6;
462:     }
463:   }
464: 
465:   onKeyUp(e) {
466:     this.keys[e.code] = false;
467:     if (e.code === 'KeyH') this.audio.setHorn(false);
468:   }
