810:   // ------------------------------------------------------------- simulation
811:   readInput() {
812:     let throttle = 0, brake = 0, steer = 0, handbrake = 0;
813:     const k = this.keys;
814:     if (k.KeyW || k.ArrowUp) throttle = 1;
815:     if (k.KeyS || k.ArrowDown) brake = 1;
816:     if (k.KeyA || k.ArrowLeft) steer += 1;
817:     if (k.KeyD || k.ArrowRight) steer -= 1;
818:     if (k.Space) handbrake = 1;
819:     throttle += this.touch.throttle; brake += this.touch.brake; steer += this.touch.steer;
820:     const pads = navigator.getGamepads ? navigator.getGamepads() : [];
821:     const gp = pads && pads[0];
822:     if (gp) {
823:       steer += -gp.axes[0];
824:       throttle += gp.buttons[7]?.value || 0;
825:       brake += gp.buttons[6]?.value || 0;
826:       if (gp.buttons[0]?.pressed) handbrake = 1;
827:     }
828:     return {
829:       throttle: clamp(throttle, 0, 1),
830:       brake: clamp(brake, 0, 1),
831:       steer: clamp(steer, -1, 1),
832:       handbrake: handbrake > 0,
833:     };
834:   }
835: 
836:   updateDriving(dt) {
837:     const input = this.readInput();
838:     this.elapsed += dt;
839:     this.game.time = (this.game.time + dt / 60) % 24;
840:     this.truck.update(dt, input, this.world, this.settings.quality);
841:     // player position after update
842:     const pos = this.truck.group.position;
843:     this.world.update(dt, this.camera, pos, this.game.time, this.game.weather);
844:     this.traffic.update(dt, pos, this.world.isNight);
845:     this.collisionCooldown = Math.max(0, this.collisionCooldown - dt);
846:     const col = this.traffic.checkCollision(this.truck.group, this.truck.speed);
847:     if (col && this.collisionCooldown <= 0 && this.truck.speed > 1.0) {
848:       this.truck.applyImpact(clamp(this.truck.speed * 0.55, 1.2, 9));
849:       this.audio.crash();
850:       this.collisionCooldown = 1.4;
851:       this.toast('Collision! Watch the traffic.', 'bad');
852:     }
853:     // look recenter
854:     if (!this.dragging && this.state === 'driving') {
855:       this.look.yaw = damp(this.look.yaw, 0, 0.65, dt);
856:       this.look.pitch = damp(this.look.pitch, 0, 0.65, dt);
857:     }
858:     this.truck.updateCamera(this.camera, this.cameraMode, dt, this.look);
859:     // zone and speed
860:     const zoneInfo = this.world.zoneAt(pos.x, pos.z);
861:     this.game.limit = zoneInfo.limit;
862:     const kmh = this.truck.getSpeedKmh();
863:     const speeding = kmh > zoneInfo.limit + 4 && this.truck.speed > 0;
864:     this.game.speeding = speeding;
865:     if (speeding) {
866:       this.speedingTime += dt;
867:       this.fineTimer += dt;
868:       if (this.fineTimer > 6) {
869:         this.fineTimer = 0;
870:         const fine = zoneInfo.limit >= 80 ? 90 : 55;
871:         this.career.money = Math.max(0, this.career.money - fine);
872:         this.toast(`Speed fine · −€${fine}`, 'bad');
873:         this.audio.tick();
874:         this.save();
875:       }
876:     } else { this.speedingTime = 0; this.fineTimer = 0; }
877:     // navigation
878:     const target = this.game.target;
879:     if (target) {
880:       const dx = target.x - pos.x, dz = target.z - pos.z;
881:       const actual = Math.hypot(dx, dz);
882:       const bearing = Math.atan2(dx, dz);
883:       const relative = wrapAngle(bearing - this.truck.heading);
884:       const actualTravelHours = actual / 22.2 / 60;
885:       const eta = this.game.time + actualTravelHours;
886:       this.game.nav = {
887:         distance: actual * DISPLAY_SCALE,
888:         actual,
889:         relative,
890:         bearing,
891:         name: this.game.job?.to.name || 'Destination',
