364:       push(r); push(r2);
365:       indices.push(vi, vi + 2, vi + 1, vi + 1, vi + 2, vi + 3);
366:       vi += 4;
367:     }
368:     const geo = new THREE.BufferGeometry();
369:     geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
370:     geo.setAttribute('uv', new THREE.Float32BufferAttribute(new Float32Array(verts.length / 3 * 2), 2));
371:     geo.setIndex(indices);
372:     const normals = new Float32Array(verts.length);
373:     for (let i = 1; i < normals.length; i += 3) normals[i] = 1;
374:     geo.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
375:     return geo;
376:   }
