378:   _buildGuardrails() {
379:     const railMat = new THREE.MeshStandardMaterial({ color: 0xb6bab9, roughness: 0.4, metalness: 0.75 });
380:     this.railMaterial = railMat;
381:     const depotIdx = new Set();
382:     for (const d of this.depots) for (let k = -12; k <= 12; k++) depotIdx.add((d.idx + k + RING_N) % RING_N);
383:     const postGeo = new THREE.BoxGeometry(0.13, 0.95, 0.13);
384:     const posts = [];
385:     for (const side of [-1, 1]) {
386:       const off = side * 9.35;
387:       const verts = [], indices = [];
388:       let vi = 0;
389:       for (let i = 0; i < RING_N; i++) {
390:         const r = this.ring[i], r2 = this.ring[i + 1];
391:         if (depotIdx.has(i) || depotIdx.has((i + 1) % RING_N)) continue;
392:         const p = r.p, p2 = r2.p;
393:         // vertical beam strip
394:         verts.push(p.x + r.right.x * off, 0.48, p.z + r.right.z * off);
395:         verts.push(p.x + r.right.x * off, 0.86, p.z + r.right.z * off);
396:         verts.push(p2.x + r2.right.x * off, 0.48, p2.z + r2.right.z * off);
397:         verts.push(p2.x + r2.right.x * off, 0.86, p2.z + r2.right.z * off);
398:         indices.push(vi, vi + 2, vi + 1, vi + 1, vi + 2, vi + 3);
399:         vi += 4;
400:         if (i % 8 === 0 && !depotIdx.has(i)) posts.push({ p: p.clone().addScaledVector(r.right, off), yaw: Math.atan2(r.t.x, r.t.z) });
401:       }
402:       const geo = new THREE.BufferGeometry();
403:       geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
404:       geo.setIndex(indices);
405:       geo.computeVertexNormals();
406:       const rail = new THREE.Mesh(geo, railMat);
407:       rail.castShadow = false; rail.receiveShadow = true;
408:       this.group.add(rail);
409:     }
410:     const inst = new THREE.InstancedMesh(postGeo, railMat, posts.length);
411:     const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), up = new THREE.Vector3(0, 1, 0);
412:     posts.forEach((p, i) => {
413:       q.setFromAxisAngle(up, p.yaw);
414:       m4.compose(new THREE.Vector3(p.p.x, 0.42, p.p.z), q, new THREE.Vector3(1, 1, 1));
415:       inst.setMatrixAt(i, m4);
416:     });
417:     inst.instanceMatrix.needsUpdate = true;
418:     inst.castShadow = true;
419:     this.group.add(inst);
420:     // delineator posts with reflectors
421:     const delGeo = new THREE.BoxGeometry(0.1, 0.75, 0.16);
422:     const delMat = new THREE.MeshStandardMaterial({ color: 0xe8e4d8, roughness: 0.7 });
423:     const reflMat = new THREE.MeshBasicMaterial({ color: 0xff9d3c });
424:     const dels = [];
425:     for (const side of [-1, 1]) {
426:       for (let i = 0; i < RING_N; i += 13) {
427:         const r = this.ring[i];
428:         dels.push({ p: r.p.clone().addScaledVector(r.right, side * 8.9), yaw: Math.atan2(r.t.x, r.t.z) });
429:       }
430:     }
431:     const dInst = new THREE.InstancedMesh(delGeo, delMat, dels.length);
432:     const rInst = new THREE.InstancedMesh(new THREE.BoxGeometry(0.11, 0.12, 0.02), reflMat, dels.length);
433:     dels.forEach((p, i) => {
434:       q.setFromAxisAngle(up, p.yaw);
435:       m4.compose(new THREE.Vector3(p.p.x, 0.38, p.p.z), q, new THREE.Vector3(1, 1, 1));
436:       dInst.setMatrixAt(i, m4);
437:       const off = new THREE.Vector3(0, 0, 0.095).applyQuaternion(q);
438:       m4.compose(new THREE.Vector3(p.p.x + off.x, 0.6, p.p.z + off.z), q, new THREE.Vector3(1, 1, 1));
439:       rInst.setMatrixAt(i, m4);
440:     });
441:     this.group.add(dInst, rInst);
442:   }
