444:   _buildLake() {
445:     const geo = new THREE.CircleGeometry(315, 96);
446:     geo.rotateX(-Math.PI / 2);
447:     this.waterUniforms = {
448:       uTime: { value: 0 },
449:       uSky: { value: new THREE.Color('#9cc9e8') },
450:       uDeep: { value: new THREE.Color('#183d4a') },
451:       uSunDir: { value: new THREE.Vector3(0, 1, 0) },
452:       uSunColor: { value: new THREE.Color('#fff0c0') },
453:       uNight: { value: 0 },
454:     };
455:     const mat = new THREE.ShaderMaterial({
456:       uniforms: this.waterUniforms,
457:       transparent: true,
458:       vertexShader: `
459:         varying vec2 vUv; varying vec3 vPos;
460:         void main(){ vUv=uv; vPos=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }
461:       `,
462:       fragmentShader: `
463:         uniform float uTime; uniform vec3 uSky; uniform vec3 uDeep; uniform vec3 uSunDir; uniform vec3 uSunColor; uniform float uNight;
464:         varying vec2 vUv; varying vec3 vPos;
465:         float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
466:         float noise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.-2.*f);
467:           return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y); }
468:         void main(){
469:           vec2 p = vPos.xz*0.035;
470:           float n = noise(p+vec2(uTime*0.08,uTime*0.03))*0.6 + noise(p*2.1-vec2(uTime*0.05,uTime*0.09))*0.4;
471:           vec3 col = mix(uDeep, uSky, 0.45 + 0.25*n);
472:           vec3 viewDir = normalize(cameraPosition - vPos);
473:           float fres = pow(1.0 - clamp(viewDir.y,0.0,1.0), 2.5);
474:           col = mix(col, uSky, fres*0.55);
475:           vec3 nrm = normalize(vec3((n-0.5)*0.35, 1.0, (noise(p*1.7+3.0)-0.5)*0.35));
476:           float spec = pow(max(dot(reflect(-uSunDir,nrm),viewDir),0.0), 90.0);
477:           col += uSunColor*spec*(1.0-uNight)*0.9;
478:           col += vec3(0.03,0.07,0.08)*(1.0-uNight);
479:           gl_FragColor = vec4(col, 0.94);
480:         }
481:       `,
482:     });
483:     const water = new THREE.Mesh(geo, mat);
484:     water.position.y = -2.75;
485:     this.group.add(water);
486:     this.water = water;
487:     // small island
488:     const island = new THREE.Mesh(new THREE.IcosahedronGeometry(11, 2), new THREE.MeshStandardMaterial({ color: 0x667451, roughness: 1 }));
489:     island.scale.set(2.2, 0.35, 1.3);
490:     island.position.set(-70, -3.2, 85);
491:     this.group.add(island);
492:     const lighthouse = new THREE.Group();
