494:     tower.position.y = 4.5; lighthouse.add(tower);
495:     const red = cylinderMesh(1, 1, 2.2, standard(0xb63a2e, { roughness: 0.7 }));
496:     red.position.y = 9.3; lighthouse.add(red);
497:     const lightMat = new THREE.MeshBasicMaterial({ color: 0xffd98a });
498:     const lantern = cylinderMesh(0.6, 0.6, 1.1, lightMat);
499:     lantern.position.y = 10.9; lighthouse.add(lantern);
500:     lighthouse.position.set(-58, -2.7, 94);
501:     this.group.add(lighthouse);
502:     this.lighthouseLamp = lantern;
