705:   _buildScenery() {
706:     const rand = mulberry32(4242);
707:     const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5a4630, roughness: 0.95 });
708:     const leafMat = new THREE.MeshStandardMaterial({ color: 0x3c5e32, roughness: 0.85, flatShading: true });
709:     const leafMat2 = new THREE.MeshStandardMaterial({ color: 0x54733b, roughness: 0.85, flatShading: true });
710:     const positions = [];
711:     let guard = 0;
712:     while (positions.length < 1150 && guard++ < 8000) {
713:       const r = 120 + rand() * 1000;
714:       const a = rand() * TAU;
715:       const x = Math.cos(a) * r, z = Math.sin(a) * r;
716:       const y = this.groundHeight(x, z);
717:       if (y < -1.3) continue;
718:       const nr = this.nearestOnRing(x, z);
719:       if (nr.d < 22) continue;
720:       let nearDepot = false;
721:       for (const d of this.depots) {
722:         if (Math.hypot(x - d.center.x, z - d.center.z) < 70) nearDepot = true;
723:       }
724:       const radial = Math.abs(Math.hypot(x, z) - this.ringRadiusAtAngle(Math.atan2(z, x)));
725:       if (radial < 20) continue;
726:       if (nearDepot) continue;
727:       positions.push({ x, y, z, s: 0.75 + rand() * 1.15, rot: rand() * TAU, type: rand() > 0.35 ? 0 : 1 });
728:     }
729:     const trunks = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.16, 0.28, 2.4, 6), trunkMat, positions.length);
