    this.career.level = newLevel;
    this.truck.speed = 0;
    this.game.time = this.game.time % 24;
    const stars = clamp(Math.round(5 - this.truck.damage / 18 - late * 1.6), 2.5, 5);
    document.getElementById('del-pay').textContent = formatMoney(pay);

